import Button from '@mui/material/Button';
import { ThemeProvider, createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    primary: { main: '#3451b2' }
  }
});

function App() {
  return (
    <ThemeProvider theme={theme}>
      <Button variant="contained" color="primary">Save</Button>
    </ThemeProvider>
  );
}

import { useState, type FormEvent } from 'react';
import { Button, Card, CardActions, CardContent, TextField, Typography } from '@mui/material';

function EmailPreferences() {
  const [email, setEmail] = useState('');
  const [saved, setSaved] = useState(false);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaved(true);
  }

  return (
    <Card component="section" aria-labelledby="preferences-title">
      <CardContent>
        <Typography id="preferences-title" component="h2" variant="h6">
          Email preferences
        </Typography>
        <form onSubmit={handleSubmit}>
          <TextField
            label="Email address"
            type="email"
            autoComplete="email"
            required
            fullWidth
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            helperText="We will use this address for course updates."
          />
          <CardActions>
            <Button type="submit" variant="contained">Save preferences</Button>
          </CardActions>
        </form>
        {saved && <p role="status">Preferences saved locally for this example.</p>}
      </CardContent>
    </Card>
  );
}

